					},
				],
				'v2',
			),
			...addApiVersionDisplayOptions(browserUseV3Properties, 'v3'),
			...addApiVersionDisplayOptions(browserUseV4Properties, 'v4'),
		],
	};

	async execute(this: IExecuteFunctions): Promise<INodeExecutionData[][]> {
		// Resolved from the typeVersion-gated property pair above: typeVersion 1 nodes default
		// to v2, typeVersion 2 nodes default to v4.
		const apiVersion = this.getNodeParameter('apiVersion', 0, 'v2') as string;

		if (apiVersion === 'v4') {
			return executeBrowserUseV4.call(this);
		}

		if (apiVersion === 'v3') {
			return executeBrowserUseV3.call(this);
		}

		const items = this.getInputData();
		const returnData: INodeExecutionData[] = [];
		const resource = this.getNodeParameter('resource', 0) as string;
		const operation = this.getNodeParameter('operation', 0) as string;

		for (let i = 0; i < items.length; i++) {
			try {
				let responseData: any;

				if (resource === 'task') {
					if (operation === 'execute') {
						responseData = await executeTask.call(this, i);
					} else if (operation === 'get') {
						responseData = await getTask.call(this, i);
					} else if (operation === 'getMany') {
						responseData = await getTasks.call(this, i);
					} else if (operation === 'stop') {
						responseData = await stopTask.call(this, i);
					} else if (operation === 'update') {
						responseData = await updateTask.call(this, i);
					}
				}

				if (Array.isArray(responseData)) {
					returnData.push(...responseData);
				} else {
					returnData.push({
						json: responseData,
						pairedItem: {
							item: i,
						},
					});
				}
			} catch (error) {
				if (this.continueOnFail()) {
					returnData.push({
						json: {
							error: (error as any).message,
						},
						pairedItem: {
							item: i,
						},
					});
					continue;
				}
				throw toNodeError(this.getNode(), error);
			}
		}

		return [returnData];
	}
}

async function executeTask(this: IExecuteFunctions, itemIndex: number): Promise<any> {
	const task = this.getNodeParameter('task', itemIndex) as string;
	const startUrl = this.getNodeParameter('startUrl', itemIndex) as string;
	const timeout = this.getNodeParameter('timeout', itemIndex, 300) as number;
	const enableStructuredOutput = this.getNodeParameter(
		'enableStructuredOutput',
		itemIndex,
		false,
	) as boolean;
	const schemaTemplate = this.getNodeParameter('schemaTemplate', itemIndex, 'custom') as string;
	const outputSchema = this.getNodeParameter('outputSchema', itemIndex, '') as string;
	const advancedOptions = this.getNodeParameter('advancedOptions', itemIndex, {}) as any;

	const parseJsonOption = (value: unknown, fallback: any) => {
		if (!value) {
			return fallback;
		}
		if (typeof value === 'string') {
			try {
				return JSON.parse(value);
			} catch {
				return fallback;
			}
		}
		return value;
	};

	const parsedMetadata = parseJsonOption(advancedOptions.metadata, null);
	const parsedSecrets = parseJsonOption(advancedOptions.secrets, null);
	const parsedAllowedDomains = parseJsonOption(advancedOptions.allowedDomains, null);

	const metadata = {
		source: 'n8n-node',
		...(parsedMetadata && typeof parsedMetadata === 'object' && !Array.isArray(parsedMetadata)
			? parsedMetadata
			: {}),
	};

	// Validate required parameters
	if (!task.trim()) {
		throw new NodeOperationError(
			this.getNode(),
			'The "Task Description" parameter cannot be empty. Please provide a description of what you want the AI agent to do.',
			{ level: 'warning' },
		);
	}

	// Validate task length (1-20,000 characters as per API docs)
	if (task.trim().length > 20000) {
		throw new NodeOperationError(
			this.getNode(),
			'The "Task Description" exceeds the maximum length of 20,000 characters. Please shorten your description.',
			{ level: 'warning' },
		);
	}

	// Validate URL format if provided
	if (startUrl && startUrl.trim()) {
		try {
			new URL(startUrl);
		} catch {
			throw new NodeOperationError(
				this.getNode(),
				'The "Starting URL" parameter has an invalid format. Please provide a valid URL starting with http:// or https://',
				{ level: 'warning' },
			);
		}
	}

	// Validate timeout
	if (timeout < 10 || timeout > 3600) {
		throw new NodeOperationError(
			this.getNode(),
			'The "Timeout" parameter must be between 10 and 3600 seconds. Please adjust the timeout value.',
			{ level: 'warning' },
		);
	}

	// Build request body according to v2 API
	const body: any = {
		task: task.trim(),
		...(startUrl && startUrl.trim() && { startUrl: startUrl.trim() }),
		...(advancedOptions.maxSteps && { maxSteps: advancedOptions.maxSteps }),
		llm: advancedOptions.llm || 'browser-use-2.0',
		...(advancedOptions.sessionId && {
			sessionId:
				typeof advancedOptions.sessionId === 'string'
					? advancedOptions.sessionId.trim()
					: advancedOptions.sessionId,
		}),
		...(parsedAllowedDomains && Array.isArray(parsedAllowedDomains)
			? { allowedDomains: parsedAllowedDomains }
			: {}),
		...(parsedSecrets && typeof parsedSecrets === 'object' && !Array.isArray(parsedSecrets)
			? { secrets: parsedSecrets }
			: {}),
		...(advancedOptions.opVaultId && { opVaultId: advancedOptions.opVaultId }),
		...(advancedOptions.highlightElements && {
			highlightElements: advancedOptions.highlightElements,
		}),
		...(advancedOptions.flashMode && { flashMode: advancedOptions.flashMode }),
		...(advancedOptions.thinking && { thinking: advancedOptions.thinking }),
		...(advancedOptions.vision !== undefined && { vision: advancedOptions.vision }),
		...(advancedOptions.systemPromptExtension && {
			systemPromptExtension: advancedOptions.systemPromptExtension,
		}),
		...(advancedOptions.judge && { judge: advancedOptions.judge }),
		...(advancedOptions.judgeGroundTruth && {
			judgeGroundTruth: advancedOptions.judgeGroundTruth,
		}),
		...(advancedOptions.judgeLlm && { judgeLlm: advancedOptions.judgeLlm }),
		metadata,
	};

	// Add structured output if enabled
	if (enableStructuredOutput) {
		let schema: any;

		// Handle schema templates
		if (schemaTemplate && schemaTemplate !== 'custom') {
			schema = getSchemaTemplate(schemaTemplate);
		} else if (outputSchema) {
			// Only the parse belongs in the try. The validation below throws NodeOperationErrors
			// that must reach the user unchanged, and a catch around them could only re-wrap them.
			if (typeof outputSchema === 'string') {
				try {
					schema = JSON.parse(outputSchema);
				} catch (error) {
					throw new NodeOperationError(
						this.getNode(),
						`The "Custom Data Format" has invalid JSON syntax: ${(error as any).message}. Please check your JSON format.`,
						{ level: 'warning' },
					);
				}
			} else {
				schema = outputSchema;
			}

			// Validate the parsed schema
			if (!schema || typeof schema !== 'object') {
				throw new NodeOperationError(
					this.getNode(),
					'The "Custom Data Format" must be a valid JSON object or array. Please check your JSON syntax.',
					{ level: 'warning' },
				);
			}

			// Check for common schema mistakes
			if (Array.isArray(schema)) {
				if (schema.length === 0) {
					throw new NodeOperationError(
						this.getNode(),
						'The "Custom Data Format" array cannot be empty. Please provide at least one example object to define the structure.',
						{ level: 'warning' },
					);
				}
				if (typeof schema[0] !== 'object' || schema[0] === null) {
					throw new NodeOperationError(
						this.getNode(),
						'The "Custom Data Format" array items must be objects. Example: [{"name": "string", "age": "number"}]',
						{ level: 'warning' },
					);
				}
			} else if (schema.type) {
				// If it claims to be a JSON Schema, validate basic structure
				const validTypes = ['object', 'array', 'string', 'number', 'boolean', 'null'];
				if (!validTypes.includes(schema.type)) {
					throw new NodeOperationError(
						this.getNode(),
						`The "Custom Data Format" has an unknown type "${schema.type}". Valid types are: ${validTypes.join(', ')}`,
						{ level: 'warning' },
					);
				}
				if (schema.type === 'object' && !schema.properties) {
					throw new NodeOperationError(
						this.getNode(),
						'The "Custom Data Format" object type must have a "properties" field. Please define the object structure.',
						{ level: 'warning' },
					);
				}
				if (schema.type === 'array' && !schema.items) {
					throw new NodeOperationError(
						this.getNode(),
						'The "Custom Data Format" array type must have an "items" field. Please define the array item structure.',
						{ level: 'warning' },
					);
				}
			}
		} else {
			throw new NodeOperationError(
				this.getNode(),
				'"Extract Structured Data" is enabled but no schema is provided. Please select a data template or provide a custom JSON schema.',
				{ level: 'warning' },
			);
		}

		// Validate and apply schema
		if (schema && typeof schema === 'object') {
			// Convert to proper JSON Schema format
			let validSchema = schema;

			// Helper function to convert properties to proper JSON Schema format
			const convertProperties = (properties: any): any => {
				const converted: any = {};
				for (const [key, value] of Object.entries(properties)) {
					if (typeof value === 'string') {
						// Convert simple string types like "string" to proper JSON Schema objects
						converted[key] = { type: value };
					} else if (
						value &&
						typeof value === 'object' &&
						!(value as any).type &&
						!Array.isArray(value)
					) {
						// If it's an object without a type, recursively convert it
						converted[key] = {
							type: 'object',
							properties: convertProperties(value),
						};
					} else {
						// Keep as-is if it's already properly formatted
						converted[key] = value;
					}
				}
				return converted;
			};

			if (!schema.type) {
				// If no 'type' property, wrap it in a proper JSON schema structure
				if (Array.isArray(schema)) {
					// Convert simple object to proper JSON Schema properties
					const firstItem = schema[0] || {};
					const properties = convertProperties(firstItem);

					validSchema = {
						type: 'array',
						items: {
							type: 'object',
							properties,
							required: Object.keys(firstItem),
						},
					};
				} else {
					// Convert simple object to proper JSON Schema properties
					const properties = convertProperties(schema);

					validSchema = {
						type: 'object',
						properties,
						required: Object.keys(schema),
					};
				}
			} else if (schema.type === 'object' && schema.properties) {
				// Even if it has a type, ensure all properties are properly formatted
				validSchema = {
					...schema,
					properties: convertProperties(schema.properties),
				};
			}

			// API expects stringified JSON schema
			body.structuredOutput = JSON.stringify(validSchema);
			// Enhance task description to emphasize structured output requirement
			body.task = `${body.task}\n\nIMPORTANT: Extract and return data in the exact JSON structure specified. Follow the schema strictly.`;
		}
	}

	const response = await makeApiCall.call(this, 'POST', '/tasks', body);

	if (!response.id) {
		throw new NodeOperationError(
			this.getNode(),
			'The Browser Use API returned an unexpected response without a task ID. Please try again or contact support if the issue persists.',
			{ level: 'warning' },
		);
	}

	// Poll for completion with reverse backoff
	const taskId = response.id;
	const startTime = Date.now();
	let lastStatus = '';

	while (Date.now() - startTime < timeout * 1000) {
		const taskDetails = await makeApiCall.call(this, 'GET', `/tasks/${taskId}`);

		// Log status changes for better user experience
		if (taskDetails.status !== lastStatus) {
			lastStatus = taskDetails.status;
		}

		if (taskDetails.status === 'finished') {
			// Task finished - return results regardless of isSuccess
			// isSuccess indicates if the AI agent was able to complete the task,
			// but we still return the results so users can see what happened
			return {
				...formatOutput(taskDetails),
				isSuccess: taskDetails.isSuccess,
				agentMessage: taskDetails.isSuccess
					? 'AI agent successfully completed the task'
					: 'AI agent was unable to fully complete the task',
				cloudUrl: taskDetails.sessionId
					? `https://cloud.browser-use.com/agent/${taskDetails.sessionId}`
					: null,
			};
		} else if (taskDetails.status === 'stopped') {
			throw new NodeOperationError(
				this.getNode(),
				`The task was stopped: ${taskDetails.error || taskDetails.output || 'Task execution was halted'}. Please check the task configuration and try again.`,
				{ level: 'warning' },
			);
		}

		// Continue polling without delay - API handles rate limiting
	}

	// Return partial results even if not completed
	const finalTask = await makeApiCall.call(this, 'GET', `/tasks/${taskId}`);
	return {
		...formatOutput(finalTask),
		warning: `The task did not complete within ${timeout} seconds but may still be running on the server`,
		cloudUrl: finalTask.sessionId
			? `https://cloud.browser-use.com/agent/${finalTask.sessionId}`
			: null,
	};
}

function formatOutput(taskData: any): any {
	// Always return complete task data
	return taskData;
}

async function makeApiCall(
	this: IExecuteFunctions,
	method: string,
	endpoint: string,
	body?: any,
): Promise<any> {
	const credentials = await this.getCredentials('browserUseApi');
	const options: any = {
		method,
		baseURL: getVersionedBaseUrl(credentials.baseUrl as string, 'v2'),
		url: endpoint,
		headers: {
			'Content-Type': 'application/json',
		},
		timeout: 30000,
		json: true,
	};

	if (body) {
		options.body = body;
	}

	try {
		const response = await this.helpers.httpRequestWithAuthentication.call(
			this,
			'browserUseApi',
			options,
		);
		return response;
	} catch (error: unknown) {
		const apiError = error as JsonObject;

		if ((error as any).response) {
			const statusCode = (error as any).response.status;
			const responseData = (error as any).response.data;
			const errorMessage = extractErrorMessage(error, responseData);
			const httpCode = statusCode ? String(statusCode) : undefined;

			switch (statusCode) {
				case 400:
					throw new NodeApiError(this.getNode(), apiError, {
						message: 'The request could not be processed',
						description: `${errorMessage}. Please check your parameters and try again.`,
						httpCode,
						level: 'warning',
					});
				case 401:
					throw new NodeApiError(this.getNode(), apiError, {
						message: 'Authentication was not successful',
						description: 'Please verify your API key in the credentials is correct.',
						httpCode,
						level: 'warning',
					});
				case 404:
					throw new NodeApiError(this.getNode(), apiError, {
						message: 'The requested resource could not be found',
						description: `${errorMessage}. Please verify the resource exists.`,
						httpCode,
						level: 'warning',
					});
				case 422: {
					// Provide more detailed error message for validation errors
					let detailedMessage = 'The request parameters could not be validated: ';
					if (errorMessage) {
						detailedMessage += errorMessage;
					} else {
						detailedMessage += 'One or more parameters are invalid';
					}

					// Add helpful hints for common 422 errors
					const errorText = typeof errorMessage === 'string' ? errorMessage.toLowerCase() : '';
					if (errorText.includes('schema')) {
						detailedMessage +=
							'\n\nTip: Check your JSON schema format. Properties should be objects like {"type": "string"} not just "string".';
					} else if (errorText.includes('structured')) {
						detailedMessage +=
							'\n\nTip: Ensure your structured output schema is valid JSON Schema format.';
					} else {
						detailedMessage += '\n\nTip: Check your task description, URLs, and schema format.';
					}

					throw new NodeApiError(this.getNode(), apiError, {
						message: 'The request parameters could not be validated',
						description: detailedMessage,
						httpCode,
						level: 'warning',
					});
				}
				case 429:
					throw new NodeApiError(this.getNode(), apiError, {
						message: 'Rate limit exceeded or too many concurrent sessions',
						description: 'Please try again later.',
						httpCode,
						level: 'warning',
					});
				case 500:
					throw new NodeApiError(this.getNode(), apiError, {
						message: 'The Browser Use API encountered a server issue',
						description: `${errorMessage}. Please try again later or contact support if the issue persists.`,
						httpCode,
						level: 'warning',
					});
				default:
					throw new NodeApiError(this.getNode(), apiError, {
						message: `The API request was not successful (status ${statusCode})`,
						description: `${errorMessage}. Please check your configuration and try again.`,
						httpCode,
						level: 'warning',
					});
			}
		} else if ((error as any).code === 'ECONNREFUSED') {
			throw new NodeApiError(this.getNode(), apiError, {
				message: 'Connection to the Browser Use API could not be established',
				description: 'Please verify the service is available and try again.',
				level: 'warning',
			});
		} else if ((error as any).code === 'ETIMEDOUT') {
			throw new NodeApiError(this.getNode(), apiError, {
				message: 'The request to the Browser Use API timed out',
				description: 'Please check your network connection and try again.',
				level: 'warning',
			});
		}

		throw new NodeApiError(this.getNode(), apiError, {
			message: 'An unexpected issue occurred while calling the Browser Use API',
			description: `${(error as Error).message}. Please try again or contact support if the issue persists.`,
			level: 'warning',
		});
	}
}

function extractErrorMessage(error: unknown, responseData: any): string {
	if (responseData) {
		const rawMessage =
			responseData.message ||
			responseData.error ||
			responseData.detail ||
			responseData.details ||
			(responseData.errors && Array.isArray(responseData.errors)
				? responseData.errors.join(', ')
				: '') ||
			JSON.stringify(responseData);

		return typeof rawMessage === 'string' ? rawMessage : String(rawMessage);
	}

	const fallbackMessage = (error as Error).message || 'Unknown error';
	return typeof fallbackMessage === 'string' ? fallbackMessage : String(fallbackMessage);
}

async function getTask(this: IExecuteFunctions, itemIndex: number): Promise<any> {
	const taskId = this.getNodeParameter('taskId', itemIndex) as string;

	if (!taskId || !taskId.trim()) {
		throw new NodeOperationError(
			this.getNode(),
			'The "Task ID" parameter is required. Please provide a valid task ID.',
			{ level: 'warning' },
		);
	}

	const response = await makeApiCall.call(this, 'GET', `/tasks/${taskId.trim()}`);
	return response;
}

async function getTasks(this: IExecuteFunctions, itemIndex: number): Promise<any> {
	const returnAll = this.getNodeParameter('returnAll', itemIndex, false) as boolean;
	const limit = this.getNodeParameter('limit', itemIndex, 50) as number;
	const options = this.getNodeParameter('options', itemIndex, {}) as any;

	let response = await makeApiCall.call(this, 'GET', '/tasks');

	// Filter by status if specified
	if (options.status && options.status !== 'all' && Array.isArray(response)) {
		response = response.filter((task: any) => task.status === options.status);
	}

	// Apply limit if not returning all
	if (!returnAll && Array.isArray(response)) {
		response = response.slice(0, limit);
	}

	// Return as array of items for n8n
	if (Array.isArray(response)) {
		return response.map((task: any) => ({
			json: task,
		}));
	}

	return response;
}

async function stopTask(this: IExecuteFunctions, itemIndex: number): Promise<any> {
	const taskId = this.getNodeParameter('taskId', itemIndex) as string;

	if (!taskId || !taskId.trim()) {
		throw new NodeOperationError(
			this.getNode(),
			'The "Task ID" parameter is required. Please provide a valid task ID.',
			{ level: 'warning' },
		);
	}

	// For v2 API, we can use PATCH to update the status to stopped
	const body = {
		status: 'stopped',
	};

	const response = await makeApiCall.call(this, 'PATCH', `/tasks/${taskId.trim()}`, body);

	return {
		success: true,
		message: 'Task stopped successfully',
		...response,
	};
}

async function updateTask(this: IExecuteFunctions, itemIndex: number): Promise<any> {
	const taskId = this.getNodeParameter('taskId', itemIndex) as string;
	const updateFields = this.getNodeParameter('updateFields', itemIndex, {}) as any;

	if (!taskId || !taskId.trim()) {
		throw new NodeOperationError(
			this.getNode(),
			'The "Task ID" parameter is required. Please provide a valid task ID.',
			{ level: 'warning' },
		);
	}

	if (!updateFields || Object.keys(updateFields).length === 0) {
		throw new NodeOperationError(
			this.getNode(),
			'No fields to update were provided. Please add at least one field to update in the "Update Fields" collection.',
			{ level: 'warning' },
		);
	}

	const body: any = {};

	if (updateFields.task) {
		body.task = updateFields.task;
	}

	if (updateFields.status) {
		body.status = updateFields.status;
	}

	const response = await makeApiCall.call(this, 'PATCH', `/tasks/${taskId.trim()}`, body);
	return response;
}

const assert = require('node:assert/strict');
const fs = require('node:fs');
const path = require('node:path');
const { describe, it } = require('node:test');

const { NodeApiError, NodeConnectionTypes } = require('n8n-workflow');

const { loadNode, makeCtx } = require('./helpers');

const { BrowserUse } = loadNode('BrowserUse.node.js');

const ROOT = path.join(__dirname, '..');
const NODES_DIR = path.join(ROOT, 'dist', 'nodes', 'BrowserUse');
const CREDENTIALS_DIR = path.join(ROOT, 'dist', 'credentials');

const { BrowserUseApi } = require(path.join(CREDENTIALS_DIR, 'BrowserUseApi.credentials.js'));
const packageJson = require(path.join(ROOT, 'package.json'));

/**
 * The n8n community node review rejects a package over any of these, so a regression here
 * costs a release rather than a test run. Node metadata is read from the compiled `dist/`,
 * because that is what ships and what n8n loads; the registration checks compare the source
 * tree against `package.json`, which is the pairing the review actually inspects.
 */

// Same character classes the review's no-emoji-in-options rule matches on.
const EMOJI_REGEX = /(\p{Extended_Pictographic}|\p{Regional_Indicator})/gu;

/** Collects every user-facing label in a description, however deeply nested. */
function collectLabels(value, found = []) {
	if (Array.isArray(value)) {
		for (const entry of value) collectLabels(entry, found);
		return found;
	}

	if (!value || typeof value !== 'object') {
		return found;
	}

	for (const [key, entry] of Object.entries(value)) {
		if ((key === 'name' || key === 'displayName') && typeof entry === 'string') {
			found.push(entry);
		}
		collectLabels(entry, found);
	}

	return found;
}

/** Resolves a `file:` icon reference the way n8n does: relative to the class's own directory. */
function resolveIcon(reference, directory) {
	assert.ok(reference.startsWith('file:'), `${reference} must use the file: protocol`);
	return path.join(directory, reference.slice('file:'.length));
}

function assertThemedIcon(icon, directory, label) {
	assert.equal(typeof icon, 'object', `${label} must declare light and dark icon variants`);

	const light = resolveIcon(icon.light, directory);
	const dark = resolveIcon(icon.dark, directory);

	assert.notEqual(light, dark, `${label} must use a different file per theme`);

	for (const file of [light, dark]) {
		assert.ok(file.endsWith('.svg'), `${file} must be an SVG`);
		assert.ok(fs.existsSync(file), `${file} is missing from dist/`);
	}
}

describe('community node review contract', () => {
	const { description } = new BrowserUse();

	it('is usable as an AI agent tool', () => {
		assert.equal(description.usableAsTool, true);
	});

	it('shows the current operation as its subtitle', () => {
		assert.match(description.subtitle, /^=\{\{.*\$parameter\["operation"\]/);
	});

	it('declares connections through NodeConnectionTypes rather than string literals', () => {
		assert.deepEqual(description.inputs, [NodeConnectionTypes.Main]);
		assert.deepEqual(description.outputs, [NodeConnectionTypes.Main]);
	});

	it('ships a light and a dark icon', () => {
		assertThemedIcon(description.icon, NODES_DIR, 'BrowserUse');
	});

	it('gives the credential a themed icon that resolves inside the package', () => {
		assertThemedIcon(new BrowserUseApi().icon, CREDENTIALS_DIR, 'BrowserUseApi');
	});

	it('keeps emoji out of every user-facing label, across all three API versions', () => {
		// The v3 and v4 properties are merged into this description, so one walk covers them.
		for (const value of collectLabels(description)) {
			assert.equal(
				EMOJI_REGEX.test(value),
				false,
				`"${value}" contains an emoji, which the review gate rejects`,
			);
			EMOJI_REGEX.lastIndex = 0;
		}
	});

	it('registers every node source file it ships', () => {
		// The review flags any `*.node.ts` missing from `n8n.nodes`. The v3 and v4 modules stay
		// plain property/execute exports so they never need registering.
		const sourceFiles = fs
			.readdirSync(path.join(ROOT, 'nodes', 'BrowserUse'))
			.filter((file) => file.endsWith('.node.ts'))
			.map((file) => `dist/nodes/BrowserUse/${file.replace(/\.ts$/, '.js')}`);

		assert.deepEqual(sourceFiles.sort(), [...packageJson.n8n.nodes].sort());
	});

	it('builds every node and credential it registers', () => {
		// The check above maps source names to their expected dist paths, which says nothing
		// about what the build actually emitted. n8n loads these paths and nothing else, so a
		// registration the build never produces is a node that silently fails to load.
		for (const entry of [...packageJson.n8n.nodes, ...packageJson.n8n.credentials]) {
			assert.ok(fs.existsSync(path.join(ROOT, entry)), `${entry} is registered but not built`);
		}
	});
});

describe('errors leaving a node', () => {
	const RAW_ERROR_CASES = [
		['v2', { apiVersion: 'v2', resource: 'task', operation: 'get' }],
		['v3', { apiVersion: 'v3', resource: 'session', operation: 'get' }],
		['v4', { apiVersion: 'v4', resource: 'run', operation: 'get' }],
	];

	for (const [apiVersion, params] of RAW_ERROR_CASES) {
		it(`wraps a raw ${apiVersion} failure so the UI gets node context`, async () => {
			// The ID parameter is deliberately unstubbed, so the context throws a plain Error
			// from inside execute's try block — the one path that used to escape unwrapped.
			const { ctx } = makeCtx({ params, routes: {} });

			await assert.rejects(new BrowserUse().execute.call(ctx), (error) => {
				assert.ok(error instanceof NodeApiError, `expected a NodeApiError, got ${error.name}`);
				return true;
			});
		});
	}

	it('passes an existing node error through instead of re-wrapping it', async () => {
		const { ctx } = makeCtx({
			params: { apiVersion: 'v4', resource: 'run', operation: 'get', runId: 'r1' },
			routes: { 'GET /runs/r1': () => httpNotFound() },
		});

		await assert.rejects(new BrowserUse().execute.call(ctx), (error) => {
			// The request helper already raised this with a tailored message; double-wrapping
			// would replace it with a generic one.
			assert.equal(error.message, 'The requested Browser Use resource was not found');
			return true;
		});
	});
});

function httpNotFound() {
	const error = new Error('HTTP 404');
	error.response = { status: 404, data: { detail: 'No such run' } };
	throw error;
}

const fs = require('node:fs');
const path = require('node:path');

const DIST = path.join(__dirname, '..', 'dist', 'nodes', 'BrowserUse');

if (!fs.existsSync(path.join(DIST, 'BrowserUse.node.js'))) {
	throw new Error('dist/ is missing or stale. Run `pnpm build` before `pnpm test`.');
}

const NODE = {
	name: 'Browser Use',
	type: 'browserUse',
	typeVersion: 1,
	position: [0, 0],
	parameters: {},
};

/**
 * Builds a stand-in for n8n's IExecuteFunctions so a node can be driven without a
 * live API. `routes` maps "METHOD /path" (with or without the query string) to a
 * response value or a function of the request options.
 */
function makeCtx({
	params,
	routes,
	baseUrl = 'https://api.browser-use.com/api/v2',
	items = [{ json: {} }],
}) {
	const calls = [];
	const ctx = {
		getInputData: () => items,
		getNode: () => NODE,
		continueOnFail: () => false,
		getCredentials: async () => ({ apiKey: 'bu_test', baseUrl }),
		getNodeParameter(name, _itemIndex, fallback) {
			if (Object.prototype.hasOwnProperty.call(params, name)) {
				return params[name];
			}
			if (fallback !== undefined) {
				return fallback;
			}
			throw new Error(`Test did not stub the "${name}" parameter`);
		},
		helpers: {
			async httpRequestWithAuthentication(_credentialType, options) {
				calls.push(options);
				const withQuery = `${options.method} ${options.url}`;
				const withoutQuery = `${options.method} ${options.url.split('?')[0]}`;
				const handler = routes[withQuery] ?? routes[withoutQuery];

				if (handler === undefined) {
					throw new Error(`Test did not stub the route: ${withQuery}`);
				}

				return typeof handler === 'function' ? handler(options) : handler;
			},
		},
	};

	return { ctx, calls };
}

/** Builds an error shaped like the one n8n's HTTP helper throws. */
function httpError(status, data) {
	const error = new Error(`HTTP ${status}`);
	error.response = { status, data };
	throw error;
}

function loadNode(file) {
	return require(path.join(DIST, file));
}

/**
 * Runs `fn` with `sleep` and `Date.now` replaced by a virtual clock, so polling loops
 * resolve instantly and deterministically. The node calls `sleep` as a property lookup
 * on the n8n-workflow module, so replacing the property is enough to intercept it.
 *
 * `fn` receives the list of requested sleep durations, which is what the capped-wait
 * behaviour actually asserts: a bounded final wait shows up as a short last entry.
 */
const MAX_VIRTUAL_SLEEPS = 1000;

async function withVirtualClock(fn) {
	const n8nWorkflow = require('n8n-workflow');
	const sleepDescriptor = Object.getOwnPropertyDescriptor(n8nWorkflow, 'sleep');
	const realSleep = n8nWorkflow.sleep;
	const realNow = Date.now;
	const requestedSleeps = [];
	let now = realNow.call(Date);

	Date.now = () => now;
	// The export is a getter with no setter, so plain assignment silently no-ops and
	// leaves the real sleep running against a frozen clock, which never terminates.
	Object.defineProperty(n8nWorkflow, 'sleep', {
		configurable: true,
		value: async (ms) => {
			requestedSleeps.push(ms);

			// Turns a runaway loop into a failure rather than a hung suite.
			if (requestedSleeps.length > MAX_VIRTUAL_SLEEPS) {
				throw new Error(
					`sleep called more than ${MAX_VIRTUAL_SLEEPS} times; loop does not terminate`,
				);
			}

			// Advancing the virtual clock is what lets the loop reach its deadline.
			now += Number.isFinite(ms) ? ms : 0;
		},
	});

	if (n8nWorkflow.sleep === realSleep) {
		Date.now = realNow;
		throw new Error('could not replace n8n-workflow sleep; the virtual clock would hang');
	}

	try {
		return await fn(requestedSleeps);
	} finally {
		Date.now = realNow;
		Object.defineProperty(n8nWorkflow, 'sleep', sleepDescriptor);
	}
}

module.exports = { loadNode, makeCtx, httpError, withVirtualClock };

